import { seededRandom } from "../../components/utils";

export interface DailyWord {
  lemma: string;
  slug: string;
  gloss: string | null;
  /**
   * Whether `slug` resolves to a real Atlas lemma page. Custom deck keys can
   * remain displayable even when they have no atlas/practice-shard match.
   */
  hasAtlasEntry?: boolean;
  k?: string;
  lessonTag?: string;
  cefr?: string;
  /** Part of speech, when the pool source has it — the practice-lexemes map fills the gap otherwise. */
  pos?: string | null;
  weight?: number;
  /**
   * #5434 verified example sentence for the word of the day.
   * Absent until the sentence corpus lands — the UI omits the slot quietly.
   */
  example?: string | null;
  /** English rendering of `example` (A1 scaffolding only). */
  exampleEn?: string | null;
  /** Source attribution preserved with an inventory-backed daily example. */
  exampleProvenance?: {
    source: "textbook" | "ulp";
    label: string;
    locator?: string;
    title?: string;
  };
  /** Rights status and the documented educational-use basis for that example. */
  exampleLicense?: {
    status: string;
    useBasis?: string;
  };
  /**
   * Cleaned Kaikki/Wiktionary etymology used as a beauty signal on daily cards.
   * Absent when the origin is empty, garbage, or non-Wiktionary sourced.
   */
  etymology?: string | null;
}

export function dateSeed(d: Date): number {
  return d.getFullYear() * 10000 + (d.getMonth() + 1) * 100 + d.getDate();
}

export function pickDaily<T>(pool: T[], seed: number, n: number): T[] {
  const result = [...pool];
  const rand = seededRandom(seed);
  for (let i = result.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [result[i], result[j]] = [result[j], result[i]];
  }
  return result.slice(0, Math.max(0, Math.min(n, result.length)));
}

/**
 * Deterministic numeric contribution for a deck id, for combining with `dateSeed`
 * (D10: `pickDaily(deckPool, dateSeed(today) + deckId, 12)`). `deckId` is a string,
 * so a literal `+` would coerce the whole expression to NaN/0 — this hash gives the
 * formula's intent (date AND deck both drive the draw) a real numeric seed.
 */
export function deckSeed(deckId: string): number {
  let hash = 2166136261;
  for (let index = 0; index < deckId.length; index += 1) {
    hash ^= deckId.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

/**
 * #6132: deterministic contribution for an explicit re-roll (the learner asking to
 * see a different pick set without waiting for the calendar day to change).
 * Combines additively with `dateSeed`/`deckSeed` the same way they combine with each
 * other. `count` is 0 for the day's default draw and increments once per re-roll tap;
 * multiplying by a large prime keeps consecutive counts from producing near-identical
 * permutations under `pickDaily`'s mulberry32-style generator.
 */
export function reRollSeed(count: number): number {
  return (count * 104729) >>> 0;
}

